package com.smarthub.plus;
import android.content.*;import android.graphics.Color;import android.view.*;import android.widget.*;import java.util.*;
/** Same real-data cards in the remote-controlled sports page and non-focusable TV infobar. */
final class MatchTickerView extends HorizontalScrollView {
 private final LinearLayout line;private String signature="";
 MatchTickerView(Context c){super(c);setHorizontalScrollBarEnabled(false);setLayoutDirection(View.LAYOUT_DIRECTION_LTR);line=new LinearLayout(c);line.setGravity(Gravity.CENTER_VERTICAL);addView(line);}
 void bind(List<SportsMatch> matches){StringBuilder k=new StringBuilder();for(SportsMatch m:matches)k.append(m.id).append(m.score()).append(m.state()).append(m.minute);if(k.toString().equals(signature))return;signature=k.toString();line.removeAllViews();int count=0;for(SportsMatch m:matches){if(count++>=50)break;LinearLayout card=new LinearLayout(getContext());card.setGravity(Gravity.CENTER_VERTICAL);card.setPadding(dp(10),dp(4),dp(10),dp(4));card.setFocusable(true);card.setClickable(true);card.setBackgroundColor(0xe6132939);card.setOnFocusChangeListener((v,on)->v.setBackgroundColor(on?0xff236d77:0xe6132939));ImageView h=logo(m.home),a=logo(m.away);card.addView(h,new LinearLayout.LayoutParams(dp(36),dp(36)));TextView text=new TextView(getContext());text.setTextColor(Color.WHITE);text.setTextSize(12);text.setMaxLines(3);text.setText(m.home+"  "+m.score()+"  "+m.away+"\n"+m.league+" · "+m.state()+(!m.minute.isEmpty()?" "+m.minute:"")+"\n"+m.time()+" · Baghdad");card.addView(text,new LinearLayout.LayoutParams(dp(290),-2));card.addView(a,new LinearLayout.LayoutParams(dp(36),dp(36)));TeamLogoManager.bind(getContext(),h,m.homeId,m.homeLogo);TeamLogoManager.bind(getContext(),a,m.awayId,m.awayLogo);card.setOnClickListener(v->getContext().startActivity(new Intent(getContext(),MatchDetailsView.class).putExtra("match_id",m.id).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-2,-1);p.rightMargin=dp(6);line.addView(card,p);}if(matches.isEmpty()){TextView empty=new TextView(getContext());empty.setTextColor(0xffb4c9d8);empty.setText("No source matches in this filter · لا توجد مباريات منشورة لهذا المرشح");empty.setPadding(dp(12),dp(8),dp(12),dp(8));line.addView(empty);}}
 private ImageView logo(String name){ImageView i=new ImageView(getContext());i.setScaleType(ImageView.ScaleType.FIT_CENTER);i.setContentDescription(name+" badge");return i;}private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
}
